'use client'

import * as React from 'react'
import {
  avatarFallbackVariants,
  avatarImageVariants,
  avatarMachine,
  avatarVariants,
  cn,
} from "@/lib/utils"

import { useMachine } from '../hooks/use-machine'

const AvatarContext = React.createContext<{
  state: any
  send: (event: any) => void
} | null>(null)

function useAvatar() {
  const context = React.useContext(AvatarContext)
  if (!context) {
    throw new Error('Avatar components must be used within Avatar')
  }
  return context
}

const Avatar = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const [state, send] = useMachine(avatarMachine, {
      context: {},
    })

    const contextValue = React.useMemo(
      () => ({
        state,
        send,
      }),
      [state, send]
    )

    return (
      <AvatarContext.Provider value={contextValue}>
        <div ref={ref} data-slot="avatar" className={cn(avatarVariants(), className)} {...props} />
      </AvatarContext.Provider>
    )
  }
)
Avatar.displayName = 'Avatar'

const AvatarImage = React.forwardRef<
  HTMLImageElement,
  React.ImgHTMLAttributes<HTMLImageElement> & { onLoadingStatusChange?: (status: any) => void }
>(({ className, src, srcSet, alt, onLoadingStatusChange, ...props }, ref) => {
  const { send, state } = useAvatar()
  const imageLoaded = state.context.loaded
  const hasError = state.context.error
  const [resolvedSrc, setResolvedSrc] = React.useState<string | undefined>(undefined)

  React.useEffect(() => {
    if (!src) {
      setResolvedSrc(undefined)
      return
    }
    if (typeof src === 'string') {
      setResolvedSrc(src)
      return
    }
    const objectUrl = URL.createObjectURL(src)
    setResolvedSrc(objectUrl)
    return () => {
      URL.revokeObjectURL(objectUrl)
    }
  }, [src])

  // Image Loading Logic
  React.useEffect(() => {
    if (!resolvedSrc) {
      send({ type: 'ERROR' })
      return
    }

    const image = new Image()
    image.src = resolvedSrc
    if (srcSet && typeof src === 'string') image.srcset = srcSet

    const onload = () => send({ type: 'LOADED' })
    const onerror = () => send({ type: 'ERROR' })

    image.onload = onload
    image.onerror = onerror

    if (image.complete) onload()

    return () => {
      image.onload = null
      image.onerror = null
    }
  }, [resolvedSrc, src, srcSet, send])

  if (hasError) return null

  return (
    <img
      ref={ref}
      src={resolvedSrc}
      srcSet={srcSet}
      alt={alt}
      data-slot="avatar-image"
      className={cn(avatarImageVariants(), className)}
      {...props}
    />
  )
})
AvatarImage.displayName = 'AvatarImage'

const AvatarFallback = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const { state } = useAvatar()
    const loaded = state.context.loaded

    // Show fallback if NOT loaded (loading or error)
    if (loaded) return null

    return (
      <div
        ref={ref}
        data-slot="avatar-fallback"
        className={cn(avatarFallbackVariants(), className)}
        {...props}
      />
    )
  }
)
AvatarFallback.displayName = 'AvatarFallback'

export { Avatar, AvatarImage, AvatarFallback }

import { type ComputedRef, inject, provide } from 'vue'
import type { AvatarApi } from "@/lib/utils"

export const AvatarContextKey = Symbol('AvatarContext')

export function provideAvatarContext(api: ComputedRef<AvatarApi>) {
    provide(AvatarContextKey, api)
}

export function useAvatarContext(): ComputedRef<AvatarApi> {
    const context = inject<ComputedRef<AvatarApi>>(AvatarContextKey)
    if (!context) {
        throw new Error('useAvatarContext must be used within an AvatarProvider')
    }
    return context
}

import { normalizeProps, useMachine } from '@zag-js/vue'
import { avatarConnect, avatarMachine } from "@/lib/utils"
import { computed } from 'vue'

export type UseAvatarProps = {
    id?: string
}

export function useAvatar(props: UseAvatarProps = {}) {
    const service = useMachine(avatarMachine, {
        id: props.id,
    })

    return computed(() => avatarConnect(service, normalizeProps))
}

import { avatarVariants } from '../utils'

Component({
  properties: {
    extClass: { type: String, value: '' },
  },
  data: {
    className: '',
    loaded: false,
    error: false,
  },
  lifetimes: {
    attached() {
      this._syncClassName()
    },
  },
  relations: {
    '../avatar-image/index': {
      type: 'child',
      linked() {
        this._syncChildren()
      },
      linkChanged() {
        this._syncChildren()
      },
    },
    '../avatar-fallback/index': {
      type: 'child',
      linked() {
        this._syncChildren()
      },
      linkChanged() {
        this._syncChildren()
      },
    },
  },
  observers: {
    extClass() {
      this._syncClassName()
    },
  },
  methods: {
    _syncClassName() {
      this.setData({
        className: avatarVariants({ className: this.properties.extClass }),
      })
    },
    handleImageLoaded() {
      this.setData({ loaded: true, error: false })
      this._syncChildren()
    },
    handleImageError() {
      this.setData({ loaded: false, error: true })
      this._syncChildren()
    },
    _syncChildren() {
      const imageNodes = this.getRelationNodes('../avatar-image/index')
      const fallbackNodes = this.getRelationNodes('../avatar-fallback/index')
      const { loaded, error } = this.data

      imageNodes.forEach((node: any) => {
        node.setData({ hidden: error })
      })
      fallbackNodes.forEach((node: any) => {
        node.setData({ hidden: loaded && !error })
      })
    },
  },
})

import { avatarFallbackVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  relations: {
    '../avatar/index': {
      type: 'parent',
      linked(target) {
        this.parent = target
      },
      unlinked() {
        this.parent = null
      },
    },
  },
  properties: {
    extClass: { type: String, value: '' },
  },
  data: {
    className: '',
    hidden: false,
  },
  lifetimes: {
    attached() {
      this._syncClassName()
    },
  },
  observers: {
    extClass() {
      this._syncClassName()
    },
  },
  methods: {
    _syncClassName() {
      this.setData({
        className: avatarFallbackVariants({ className: this.properties.extClass }),
      })
    },
  },
})

import { avatarImageVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  relations: {
    '../avatar/index': {
      type: 'parent',
      linked(target) {
        this.parent = target
      },
      unlinked() {
        this.parent = null
      },
    },
  },
  properties: {
    src: { type: String, value: '' },
    alt: { type: String, value: '' },
    extClass: { type: String, value: '' },
  },
  data: {
    className: '',
    hidden: false,
  },
  lifetimes: {
    attached() {
      this._syncClassName()
    },
  },
  observers: {
    extClass() {
      this._syncClassName()
    },
  },
  methods: {
    _syncClassName() {
      this.setData({
        className: avatarImageVariants({ className: this.properties.extClass }),
      })
    },
    onLoad() {
      if (this.parent?.handleImageLoaded) {
        this.parent.handleImageLoaded()
      }
    },
    onError() {
      if (this.parent?.handleImageError) {
        this.parent.handleImageError()
      }
    },
  },
})
